    "SENTINEL2_L2A",
    temporal_extent=c("2024-06-01", "2024-06-30"),
    bands=c("B04", "B08")
)

study_area &lt;- cube$filter_bbox(
    west=4.30, east=4.55, south=50.80, north=50.98, crs="EPSG:4326"
)


